'use client'

import { useAppContext } from '@/app/context/app-context'
import { Box, Typography } from '@mui/material'

import theme from '../../../theme'
import ChatArea from '@/app/ui/nano-banana-components/ChatArea'
import ChatPromptInput from '@/app/ui/nano-banana-components/ChatPromptInput'
import { AssetImages, ChatMessageContent, ChatMessageRole } from '@/app/api/nano-banana/nano-banana.types'
import { useState } from 'react'
import { Part } from '@google/genai'
import { generateImage } from '@/app/api/nano-banana/action'

const { palette } = theme

const fakeContents: ChatMessageContent[] = [
  {
    role: ChatMessageRole.USER,
    parts: [{ text: 'Show me a random abstract image.' }],
  },
  {
    role: ChatMessageRole.MODEL,
    parts: [
      { text: 'Here is one:' },
      {
        inlineData: {
          mimeType: 'image/png',
          data: '',
        },
      },
    ],
  },
  {
    role: ChatMessageRole.USER,
    parts: [{ text: 'Now give me another.' }],
  },
  {
    role: ChatMessageRole.MODEL,
    parts: [
      { text: 'Okay:' },
      {
        inlineData: {
          mimeType: 'image/png',
          data: '',
        },
      },
    ],
  },
  {
    role: ChatMessageRole.USER,
    parts: [{ text: 'Give me a PNG of size 64×64.' }],
  },
  {
    role: ChatMessageRole.MODEL,
    parts: [
      { text: 'Here is a 64×64 sample:' },
      {
        inlineData: {
          mimeType: 'image/png',
          data: '',
        },
      },
    ],
  },
  {
    role: ChatMessageRole.USER,
    parts: [{ text: 'What about a text-only content?' }],
  },
  {
    role: ChatMessageRole.MODEL,
    parts: [{ text: 'Sure — no inline data here, just text.' }],
  },
  {
    role: ChatMessageRole.USER,
    parts: [{ text: 'Finally, send me a fun fact image + caption.' }],
  },
  {
    role: ChatMessageRole.MODEL,
    parts: [
      { text: 'Fun fact: Honey never spoils!' },
      {
        inlineData: {
          mimeType: 'image/png',
          data: '',
        },
      },
    ],
  },
  {
    role: ChatMessageRole.USER,
    parts: [{ text: 'Give me a PNG of size 1024x1024.' }],
  },
  {
    role: ChatMessageRole.MODEL,
    parts: [
      { text: 'Here a random image of 1024x1024 !' },
      {
        inlineData: {
          mimeType: 'image/png',
          data: '',
        },
      },
    ],
  },
]

export default function Page() {
  const { appContext, error: appContextError, setAppContext } = useAppContext()
  const [messages, setMessages] = useState<ChatMessageContent[]>(fakeContents)
  const [loading, setLoading] = useState(false)

  if (appContext?.isLoading) {
    return (
      <Box p={5}>
        <Typography
          variant="h3"
          sx={{ fontWeight: 400, color: appContextError ? palette.error.main : palette.primary.main }}
        >
          {appContextError
            ? 'Error loading your profile content! Retry or contact you IT admin.'
            : 'Loading your profile content...'}
        </Typography>
      </Box>
    )
  }

  async function generateContent(fullMessages: ChatMessageContent[]) {
    setLoading(true)
    const response = await generateImage(fullMessages)
    if ('error' in response) {
      // TODO handle error
      console.error(response)
    } else {
      setMessages((prev) => [...prev, response])
    }
    setLoading(false)
  }

  async function onPromptHandler(prompt?: string, images?: AssetImages[]) {
    console.log('sibmtied', prompt, images)
    const parts: Part[] = []
    if (prompt) {
      parts.push({ text: prompt })
    }

    const imageParts =
      images?.map((image) => ({
        inlineData: {
          mimeType: image.fileType,
          // displayName: image.fileName,
          data: image.rawBase64,
        },
      })) ?? []

    if (imageParts.length > 0) {
      parts.push(...imageParts)
    }

    const message: ChatMessageContent = { role: ChatMessageRole.USER, parts }
    console.log('message by user', message)
    const fullMessages = [...messages, message]
    setMessages(fullMessages)
    await generateContent(fullMessages)
  }

  return (
    <Box
      p={2}
      sx={{
        maxHeight: '100vh',
        width: '100%',
        display: 'flex',
        flexDirection: 'column',
        gap: 2,
      }}
    >
      <Box
        id="header"
        sx={{
          py: 2,
          borderBottom: 1,
          borderColor: theme.palette.secondary.light,
        }}
      >
        <Typography display="inline" variant="h1" color={palette.text.secondary} sx={{ fontSize: '1.8rem' }}>
          Generate Images with
        </Typography>
        <Typography
          display="inline"
          variant="h1"
          color={palette.primary.main}
          sx={{ fontWeight: 500, fontSize: '2rem', pl: 1 }}
        >
          Nano Banana
        </Typography>
      </Box>
      <Box sx={{ flex: 1, display: 'flex', flexDirection: 'column', overflow: 'hidden' }}>
        <Box sx={{ flex: 1, overflowY: 'auto' }}>
          <ChatArea contents={messages} generating={loading} />
        </Box>
      </Box>
      <ChatPromptInput onPrompt={onPromptHandler} />
    </Box>
  )
}
